@section('content')<div class="auth-card"><h1>{{ __('messages.submission_complete') }}</h1><p>{{ __('messages.submission_status') }}: <strong>{{ $submission->status }}</strong></p>@if($submission->publication->result_visibility==='score'&&in_array($submission->status,['graded','submitted']))<div class="score-card"><strong>{{ $submission->final_points }} / {{ $submission->maximum_points }}</strong><span>{{ $submission->percentage }}%</span></div>@elseif($submission->grading_status==='awaiting_grading')<p>{{ __('messages.review_pending') }}</p>@endif @if($submission->publication->correct_answers_visible&&$submission->submitted_at)<section class="stack my-6"><h2>{{ __('messages.correct_answers') }}</h2>@foreach($submission->answers as $answer)<article class="card"><strong>{{ $answer->component->label }}</strong><p>{{ __('messages.answer') }}: {{ $answer->display_value }}</p>@if($answer->component->scoringRule)<p>{{ __('messages.correct_answers') }}: {{ is_array(data_get($answer->component->scoringRule->rules,'correct'))?implode(', ',data_get($answer->component->scoringRule->rules,'correct')):data_get($answer->component->scoringRule->rules,'correct') }}</p>@endif</article>@endforeach</section>@endif<a class="btn" href="{{ auth()->check()?route('dashboard'):route('publications.show',$submission->publication) }}">{{ __('messages.back') }}</a></div>@endsection
